cat > /tmp/diff.pl <<'PERL'
use strict; use warnings;
my $BIN="/workspace/dataset/test16_executable";
sub hv { my $h=shift; return 0 if $h eq ''; return $h =~ /^[A-Za-z0-9\-\.\[\]]+$/ ? 1 : 0; }
sub host_theirs {
  my $s=shift; my $i=index($s,"://"); return '' if $i<0;
  my $rest=substr($s,$i+3);
  my @p=grep {$_>=0} map {index($rest,$_)} ('/','?','#');
  my $auth = @p ? substr($rest,0,(sort {$a<=>$b} @p)[0]) : $rest;
  my $a=index($auth,'@'); my $hp = $a>=0 ? substr($auth,$a+1) : $auth;
  my $c=index($hp,':'); return $c>=0 ? substr($hp,0,$c) : $hp;
}
sub host_mine {
  my $s=shift;
  my $f=index($s,'#'); $s=substr($s,0,$f) if $f>=0;
  my $q=index($s,'?'); $s=substr($s,0,$q) if $q>=0;
  my $i=index($s,"://"); return '' if $i<0;
  my $rest=substr($s,$i+3);
  my $sl=index($rest,'/'); my $auth = $sl>=0 ? substr($rest,0,$sl) : $rest;
  my $a=index($auth,'@'); my $hp = $a>=0 ? substr($auth,$a+1) : $auth;
  my $c=index($hp,':'); return $c>=0 ? substr($hp,0,$c) : $hp;
}
my @alpha=('a','b','1','9','[',']',':','@','/','?','#','-','.','_',' ','%','://','::','[::1]','A');
srand(11);
my @cases;
for (1..6000){ my $n=1+int(rand(8)); my $s=''; $s.=$alpha[int(rand(scalar @alpha))] for (1..$n); push @cases,$s; }
push @cases, ('http#x://[::1]','htt?p://[a]','http://[::1]:80','x#://a','http://[a:70000]:80','http://[a:b]:1');
my ($bt,$bm,@et,@em)=(0,0);
for my $s (@cases){
  my @out = split /\n/, `'$BIN' "\Q$s\E" 2>/dev/null`;
  next if scalar(@out) < 4;
  my $act=$out[2];
  my $pt=hv(host_theirs($s)); my $pm=hv(host_mine($s));
  if("$pt" ne "$act"){ $bt++; push @et,[$s,$pt,$act] if @et<20; }
  if("$pm" ne "$act"){ $bm++; push @em,[$s,$pm,$act] if @em<20; }
}
printf "cases=%d  THEIR mismatches=%d  MINE mismatches=%d\n",scalar(@cases),$bt,$bm;
print "--- THEIR model failures ---\n"; for(@et){ printf "%-24s pred=%s actual=%s\n", "'".$_->[0]."'", $_->[1],$_->[2]; }
print "--- MY model failures ---\n"; for(@em){ printf "%-24s pred=%s actual=%s\n", "'".$_->[0]."'", $_->[1],$_->[2]; }
PERL
